import copy,json
from work import evaluate
with open('policy.json') as f: p=json.load(f)
with open('requests.json') as f: rs=json.load(f)
with open('report.json') as f: report=json.load(f)
expected=[evaluate(r,p) for r in rs]
assert report==expected
for r in rs:
 rb=copy.deepcopy(r); pb=copy.deepcopy(p); evaluate(r,p); assert r==rb and p==pb
assert evaluate({'from':'x','to':'y'},p)=={'ok':False,'value':None,'reason':'blocked'}
assert evaluate({'from':'ready','to':'running','role':'wrong','retry':True,'attempts':0},p)=={'ok':False,'value':None,'reason':'permission'}
for bad in [None,True,False,-1,2,3,1.0,'1']:
 assert evaluate({'from':'failed','to':'ready','retry':True,'attempts':bad},p)=={'ok':False,'value':None,'reason':'retry_limit'}, bad
for good in [0,1]:
 assert evaluate({'from':'failed','to':'ready','retry':True,'attempts':good},p)=={'ok':True,'value':'ready','reason':'ok'}
assert evaluate({'from':'failed','to':'ready'},p)=={'ok':True,'value':'ready','reason':'ok'}
print('all checks passed')

